  "wp.message.26a6374fbf59": "Pixflow アドオンを起動できませんでした。Pixflow プラグインの互換性を確認して再読み込みしてください。他の機能は引き続き利用できる場合があります。",
  "wp.message.ca7714cffbcc": "Pro を有効化",
  "wp.message.197c83a2f752": "Pro アドオンでプレミアムツールを復元できます。ライセンス、コンテンツ、保存済み設定は保持されます。Bricks の二要素認証を使用していた場合は、Pro の有効化後に設定で再度有効にしてください。",
  "wp.message.2ffdcbc380ea": "お気に入りのビルダーで制作。注釈、音声、デザインシステム、画像生成をワークフローに追加できます。",
  "wp.message.40ed1102964b": "Pro の試用を確認",
  "wp.message.e9cccd3ef5fc": "非表示の設定を保存できませんでした。再試行してください。",
  "wp.message.1372089fb797": "Pixflow Pro バナーを閉じる",
  "wp.message.5e3ba715018d": "Pro をダウンロード",
  "wp.message.fb2e6d87b44c": "Pixflow Design Pro でもっと広がる可能性",
  "wp.message.9934717ca744": "このページを更新して再試行してください。",
  "wp.message.7c78f9990490": "Pro の 7 日間試用を開始",
  "wp.message.f89b4dcf2c2e": "Pro を 7 日間試す",
  "wp.message.69ecce9deb2d": "この通知を閉じることはできません。",
  "wp.message.927384e7eed8": "Pixflow プランに Pro が含まれています",
  "wp.message.64585a3a39ef": "[%s] 二要素認証をリセットしました",
