  "wp.message.73dbcf028ec6": "アカウント保護のため 2 つ目の認証方法を追加してください。",
  "wp.message.529da8588051": "ログイン完了には追加認証が必要です。",
  "wp.message.6b49000156c3": "すべての認証方法とリカバリーコードを失った場合、管理者がこの緊急リセットを使用できます。",
  "wp.message.4ea44caf5d6e": "フォームの後",
  "wp.message.1be05927766c": "管理者がアカウントの二要素認証を解除しました。心当たりがない場合は、直ちにパスワードを変更し、サイト管理者に連絡してください。",
