  "ui.abilityDisplay.c5f4749aa90c": "WordPress 管理画面のコンテキスト、コンテンツ、タクソノミー、メディア、設定へのアクセスを範囲限定で提供します。",
  "ui.abilityDisplay.92866e333805": "Pixflow アダプターを選択する前に、有効な Admin and Site Enhancements 系統を検出します。",
  "ui.abilityDisplay.2e8274215c12": "将来のリソース限定アダプターに向け、Pods のコンテンツモデル API を検出します。",
  "ui.abilityDisplay.a4328d19d146": "投稿タイプ、タクソノミー、メタボックス、オプションページに Pixflow 専用アダプターを使用します。",
  "ui.abilityDisplay.23e57b90f610": "ACF が有効な場合、Pixflow 専用の ACF スキーマ・値アダプターを使用します。",
  "ui.abilityDisplay.c3786eb7a892": "Meta Box のフィールド、投稿タイプ、タクソノミー、関連付け API を検出します。",
  "ui.abilityDisplay.cc0694349fe8": "将来の型付きアダプターに向け、ACPT コンテンツモデル API を検出します。",
  "ui.abilityDisplay.6b028b4bce38": "認証情報を除外し、Yoast SEO の投稿・タームのメタデータを検出します。",
  "ui.abilityDisplay.92f775a130bb": "Rank Math SEO の設定、スキーマ、メタデータ API を検出します。",
  "ui.abilityDisplay.92f255e00a2b": "All in One SEO のメタデータ・リダイレクト機能を検出します。",
  "ui.abilityDisplay.78767faf0a43": "SEOPress のメタデータ、スキーマ、リダイレクト機能を検出します。",
  "ui.abilityDisplay.4dac7179a6f4": "Pixflow 専用の Bricks 管理状態・テンプレート/設定アダプターを使用します。",
  "ui.abilityDisplay.38c4fdc9a949": "汎用的なビルダー書き込みを行わず、Bricksforge のツールとカスタム要素を検出します。",
  "ui.abilityDisplay.a48d9c59abd6": "Elementor 文書のライブ編集、インストール済み要素のスキーマ、ネイティブ保存と履歴。Pro・アドオン要素はインストール時のみ利用できます。",
  "ui.abilityDisplay.6e4fc6ca4d16": "ビルダーの保存データを編集せず、Divi テーマとビルダー API を検出します。",
  "ui.abilityDisplay.259952aa43e3": "Avada テーマと Fusion Builder の機能を検出します。",
  "ui.abilityDisplay.ca2ad76ff641": "投稿メタデータを直接変更せず、WPBakery のコンテンツと要素スキーマを検出します。",
  "ui.abilityDisplay.a438c345f22f": "将来のネイティブアダプターに向け、Breakdance のエディター・テンプレート API を検出します。",
  "ui.abilityDisplay.aa45aaa33ee8": "旧式の安全でないルートには対応せず、Oxygen のビルダー/テーマ API を検出します。",
  "ui.abilityDisplay.fdda9ed705e6": "Mosaic のデザインシステム・テンプレート機能を検出します。",
  "ui.abilityDisplay.bcbf1f09fcf0": "Etch のテンプレート、ノード、クエリ、カスタムフィールド機能を検出します。",
  "ui.abilityDisplay.eb43e12d454a": "Beaver Builder のレイアウトとモジュールスキーマを検出します。",
  "ui.abilityDisplay.ab634fc656f2": "GeneratePress のテーマ、Elements、Site Library、カスタマイザー機能を検出します。",
  "ui.abilityDisplay.c9bb9ff824dc": "GenerateBlocks のネイティブ Gutenberg スキーマと編集、生成スタイル、インストール済み Free/Pro 機能。",
  "ui.abilityDisplay.110f7217b07a": "Kadence のテーマ設定とデザインシステムのメタデータを検出します。",
  "ui.abilityDisplay.a97ac2d717c6": "認証情報を漏らさず、Astra のテーマ・Pro モジュール設定を検出します。",
  "ui.abilityDisplay.b67e802289de": "Voxel の投稿タイプ、フィールド、テンプレート、コマース機能を検出します。",
  "ui.abilityDisplay.8ae5caa5f9ed": "Kadence Blocks のスキーマとブロックの有効化状態を検出します。",
  "ui.abilityDisplay.e04042e6f65a": "Spectra One のテーマテンプレート、パターン、スタイルバリエーションを検出します。",
  "ui.abilityDisplay.138c3d99edaa": "Spectra のブロック、ポップアップ、フォーム、設定スキーマを検出します。",
  "ui.abilityDisplay.5536f3eb2784": "OceanWP のテーマ、Ocean Extra、カスタマイザー、WooCommerce 機能を検出します。",
  "ui.abilityDisplay.510661870cef": "WooCommerce のカタログ・ストア設定を検出します。決済やチェックアウトに影響する操作は公開しません。",
  "ui.abilityDisplay.530f12ba9d3f": "Code Snippets の状態のみ検出します。コードの作成、編集、有効化、評価実行は禁止されています。",
  "ui.abilityDisplay.cdd61e9e3aab": "WPCode の状態のみ検出します。スニペットの作成、編集、有効化、評価実行は禁止されています。",
  "ui.abilityDisplay.0eee3a5141dc": "型付きスニペット記録と通常の条件に Pixflow 専用ネイティブアダプターを使用します。eval による実行ルートは利用できません。",
  "ui.abilityDisplay.4cbeca33698e": "Dynamic Shortcodes の状態のみ検出します。評価・コード実行は利用できません。",
  "ui.abilityDisplay.bd2f328a438e": "送信を行わず、Contact Form 7 のフォームとスキーマを検出します。",
  "ui.abilityDisplay.18b172722b53": "送信記録の公開や通知送信を行わず、WPForms のフォーム・フィールドスキーマを検出します。",
  "ui.abilityDisplay.372c4d1b0bdc": "送信記録と外部送信を対象外とし、Gravity Forms のスキーマを検出します。",
  "ui.abilityDisplay.9d06fd0c946f": "送信、決済、通知を発生させず、Fluent Forms のスキーマを検出します。",
  "ui.abilityDisplay.d1073daec834": "送信記録や決済を含めず、Formidable のフォーム・フィールド定義を検出します。",
  "ui.abilityDisplay.3763fb901533": "送信、メール、連携を行わず、Ninja Forms のスキーマを検出します。",
  "ui.abilityDisplay.02620d270c2e": "API キーを変更せず、Weglot の言語、除外、翻訳 URL の設定機能を検出します。",
