  "ui.finalDesignFlow.0e94726136": "エージェントツールは Composio GitHub コネクターでアクセスできます。リポジトリ URL はローカル git や GitHub CLI でも引き続き利用できます。",
  "ui.finalDesignFlow.723772b0a0": "このプロジェクトでコネクター経由の GitHub ツールが必要な場合のみ、Composio API キーを追加してください。",
  "ui.finalDesignFlow.21f5844795": "このデバイスでリポジトリを読めない場合、Composio GitHub コネクターを代替として利用できます。",
  "ui.finalDesignFlow.f32b39ae4f": "Composio 認証ウィンドウで手続きを完了してください。ローカルの GitHub 取り込みは引き続き利用できます。",
  "ui.finalDesignFlow.2a0d6e82a3": "バックグラウンドでコネクターの状態を確認しています。URL からの取り込みは継続できます。",
  "ui.finalDesignFlow.5d652ac7d4": "Composio GitHub コネクターを再接続するか、ローカル git/GitHub CLI で続行してください。",
  "ui.finalDesignFlow.c8f1da9e35": "このデザインシステムを更新：",
  "ui.finalDesignFlow.bc0ac039a0": "Composio GitHub コネクターは {account} として接続済みです。このデバイスでリポジトリを読めない場合の代替として利用できます。",
