  "ui.seoAudit.theHomepageHoldsItsGoogleAnalytics_c856d366": "ホームページには、分析の同意が得られるまでGoogle Analyticsのタグが保持されます。同意を拒否した場合のアクセスは、GA4から除外される可能性があるため、レポートされたオーガニックトラフィックは実際の訪問数を過小評価する可能性があります。",
  "ui.seoAudit.theHomepageSetsAnalyticsStorageTo_36c513cb": "ホームページでは、デフォルトで分析データの保存を拒否設定にしています。GA4は、クッキーを使用しないデータ収集の限定的な情報を受け取り、モデリングを使用する可能性があります。これらの数値は、訪問の完全なカウントとして解釈すべきではありません。",
  "ui.seoAudit.theIntendedReferringPageContainsA_53634050": "意図された参照ページには、このページへのアクセス可能なリンク（公開HTMLリンク）が含まれているか、または所有者がリンクされていないページを意図的に記録しています。",
  "ui.seoAudit.theIntendedSectionIdExistsOn_6e2cf497": "意図されたセクションIDは、アクセス可能な宛先ページに存在するか、参照リンクが修正または削除されています。",
  "ui.seoAudit.theNamedBrokenLinksAreRemoved_942eff46": "意図された壊れたリンクが削除または、アクセス可能な宛先ページに置き換えられます。廃止されたURLは、引き続き廃止されます。",
